/* counter.h - the interface: deployed without counter.c */
typedef struct Counter Counter;      /* opaque, incomplete type */
Counter *counter_new(int start);
int  counter_inc(Counter *c);
void counter_free(Counter *c);
/* counter.c - the implementation, linked in elsewhere */
struct Counter { int value; };
int counter_inc(Counter *c) { return ++c->value; }

